require dirname(__DIR__).'/includes/bootstrap.php';require APP_ROOT.'/services/dat_coc.php';$me=require_role(['KHACH_HANG']);$vin=get('vin')?:post('vin');
handle_form(function()use($me,$vin){must(post('agree')==='1','Cần đồng ý điều kiện giữ xe và đặt cọc.');$id=(new KhachHang($me))->datCoc($vin,post('ma_km'),post('request_key'),post('bao_gia_id')!==''?(int)post('bao_gia_id'):null);flash('Đã tạo đơn và giữ xe tạm thời. Hãy thanh toán trong hạn giữ.');redirect('khach_hang/don_mua.php?id='.$id);},'khach_hang/dat_coc.php?vin='.rawurlencode($vin));
$x=db_one('SELECT x.*,c.gia_niem_yet,c.ten_cau_hinh,d.ten_dong_xe FROM xe x JOIN cau_hinh_xe c ON c.ma_cau_hinh=x.ma_cau_hinh JOIN dong_xe d ON d.ma_dong_xe=x.ma_dong_xe WHERE x.so_khung_vin=? AND c.hien_thi=1 AND d.hien_thi=1',[$vin]);must((bool)$x,'Xe không tồn tại.',404);
page_start('Đặt cọc giữ xe',$x['ten_dong_xe'].' '.$x['ten_cau_hinh'].' · VIN '.$vin);echo '<div class="auth panel"><p class="price">'.e(money($x['gia_niem_yet'])).'</p><p>Giữ tạm '.(int)setting('hold_minutes').' phút. Mức cọc tối đa '.e(money(setting('deposit_vnd'))).'.</p>';token_form();field('vin','',$vin,'hidden');field('request_key','',post('request_key')?:new_request_key(),'hidden');field('ma_km','Mã ưu đãi (nếu có)',post('ma_km'));field('bao_gia_id','Mã báo giá đã nhận (nếu có)',get('bao_gia')?:post('bao_gia_id'),'number');echo '<p class="muted">Tạo đơn chưa phải đã thanh toán. Sau khi cọc thành công, nhân viên liên hệ hoàn thiện hợp đồng. Yêu cầu hủy và số tiền hoàn được xử lý theo thỏa thuận đã chốt với showroom; không tự động khấu trừ cọc.</p><label><input type="checkbox" name="agree" value="1" required>Tôi đồng ý giữ xe trong thời hạn và gửi yêu cầu đặt cọc.</label><button>Tạo đơn đặt cọc</button></form></div>';page_end();
